 const accountBalance=a=>Number(a.opening||0)+transactions.filter(t=>(t.accountId??accounts[0]?.id)===a.id).reduce((sum,t)=>sum+(t.type==='income'?1:t.type==='expense'?-1:0)*Number(t.amount||0),0);
 const totalAccounts=accounts.reduce((s,a)=>s+accountBalance(a),0),totalDebt=loans.reduce((s,l)=>s+Number(l.outstanding||0),0);
 const addAccount=()=>{const name=prompt('Account or wallet name');if(!name?.trim())return;const type=prompt('Account type: Bank, Cash, Savings, Credit card','Bank')||'Bank';const opening=Number(prompt('Opening balance (₹)','0')||0);if(!Number.isFinite(opening))return;saveList('pw_v3_accounts',[...accounts,{id:Date.now(),name:name.trim(),type,opening}],setAccounts)};
 const editAccount=a=>{const name=prompt('Account name',a.name);if(!name?.trim())return;const type=prompt('Account type',a.type)||a.type;saveList('pw_v3_accounts',accounts.map(x=>x.id===a.id?{...x,name:name.trim(),type}:x),setAccounts)};
 const reconcileAccount=a=>{const raw=prompt('Enter the actual balance shown by your bank/wallet (₹)',String(accountBalance(a)));if(raw===null||raw.trim()==='')return;const actual=Number(raw);if(!Number.isFinite(actual))return;const difference=Number((actual-accountBalance(a)).toFixed(2));if(Math.abs(difference)<0.01){alert('This account is already reconciled.');return}if(!confirm(`Create a balance adjustment of ${money(Math.abs(difference))} ${difference>0?'(increase)':'(decrease)'}?`))return;const tx={id:Date.now(),title:'Balance adjustment: '+a.name,type:difference>0?'income':'expense',amount:Math.abs(difference),category:'Balance Adjustment',date:today(),accountId:a.id,kind:'balance_adjustment',ledgerVersion:7,note:'Account reconciliation adjustment'};persist('pw_v2_transactions',[tx,...transactions],setTransactions)};
 const deleteAccount=a=>{if(accounts.length===1){alert('Keep at least one account or wallet.');return}const used=transactions.some(t=>t.accountId===a.id)||loans.some(l=>l.accountId===a.id)||investments.some(i=>i.accountId===a.id)||recurringRules.some(r=>r.accountId===a.id);let target=null;if(used){const choices=accounts.filter(x=>x.id!==a.id);const targetName=prompt('This account is linked to financial records. Reassign them to which account?\\n'+choices.map(x=>x.id+' = '+x.name).join('\\n'),choices[0].name);target=choices.find(x=>x.name===targetName||String(x.id)===targetName);if(!target)return}if(!confirm('Delete '+a.name+'?'+(used?' Linked records will be reassigned.':'')))return;if(used){persist('pw_v2_transactions',transactions.map(t=>t.accountId===a.id?{...t,accountId:target.id}:t),setTransactions);persist('pw_v3_loans',loans.map(l=>l.accountId===a.id?{...l,accountId:target.id}:l),setLoans);persist('pw_v2_investments',investments.map(i=>i.accountId===a.id?{...i,accountId:target.id}:i),setInvestments);persist('pw_v7_recurring',recurringRules.map(r=>r.accountId===a.id?{...r,accountId:target.id}:r),setRecurringRules)}saveList('pw_v3_accounts',accounts.filter(x=>x.id!==a.id),setAccounts)};
 const addTransfer=()=>{if(accounts.length<2){alert('Create at least two accounts first.');return}const fromName=prompt('Transfer FROM: '+accounts.map(a=>a.name).join(', '),accounts[0].name),from=accounts.find(a=>a.name===fromName);if(!from)return;const toName=prompt('Transfer TO: '+accounts.filter(a=>a.id!==from.id).map(a=>a.name).join(', '),accounts.find(a=>a.id!==from.id).name),to=accounts.find(a=>a.name===toName&&a.id!==from.id);if(!to)return;const amount=Number(prompt('Transfer amount (₹)'));if(!amount||amount<=0)return;const date=today(),transferId=Date.now();persist('pw_v2_transactions',transactions.concat([{id:transferId,title:'Transfer to '+to.name,type:'expense',amount,category:'Transfer',date,accountId:from.id,transfer:true,kind:'transfer',groupId:transferId},{id:transferId+1,title:'Transfer from '+from.name,type:'income',amount,category:'Transfer',date,accountId:to.id,transfer:true,kind:'transfer',groupId:transferId}]),setTransactions)};
  const addLoan=()=>{const name=prompt('Loan name');if(!name)return;const outstanding=Number(prompt('Loan amount received (₹)','0'));if(!outstanding||outstanding<=0)return;const emi=Number(prompt('Monthly EMI (₹)','0')||0);const accountId=Number(prompt('Choose account ID to receive loan amount: '+accounts.map(a=>a.id+' = '+a.name).join(', '),''+(accounts[0]?.id||1)));if(!accounts.some(a=>a.id===accountId)){alert('Invalid account ID.');return}const id=Date.now(),loan={id,name,principal:outstanding,outstanding,emi,due:today(),accountId};saveList('pw_v3_loans',[...loans,loan],setLoans);persist('pw_v2_transactions',[{id:id+1,title:'Loan received: '+name,type:'income',kind:'loan_disbursement',amount:outstanding,category:'Loan',date:today(),accountId,linkedType:'loan',linkedId:id,note:'Automatically synced from Loans & EMI'},...transactions],setTransactions)};
 const recordEMI=l=>{const amount=Number(prompt('Total EMI payment (₹)',String(l.emi||'')));if(!amount||amount<=0)return;const principal=Number(prompt('Principal portion (₹)',String(Math.min(amount,Math.max(0,Math.round(amount*.75*100)/100)))));if(!Number.isFinite(principal)||principal<0||principal>amount||principal>Number(l.outstanding)){alert('Enter a valid principal amount not exceeding the EMI or outstanding loan.');return}const interest=Number((amount-principal).toFixed(2)),accountId=l.accountId||accounts[0]?.id;if(!accountId){alert('Add an account first.');return}const groupId=Date.now(),date=today(),entries=[];if(principal>0)entries.push({id:groupId,title:'Loan principal repayment: '+l.name,type:'expense',amount:principal,category:'Loan Principal',date,accountId,kind:'loan_principal',linkedType:'loanEmi',linkedId:l.id,groupId,note:'Principal portion of EMI'});if(interest>0)entries.push({id:groupId+1,title:'Loan interest: '+l.name,type:'expense',amount:interest,category:'Interest',date,accountId,kind:'loan_interest',linkedType:'loanEmi',linkedId:l.id,groupId,note:'Interest portion of EMI'});persist('pw_v2_transactions',[...entries,...transactions],setTransactions);saveList('pw_v3_loans',loans.map(x=>x.id===l.id?{...x,outstanding:Math.max(0,Number(x.outstanding)-principal)}:x),setLoans)};

 const editLoan=l=>{const principal=Number(prompt('Original loan amount received (₹)',String(l.principal??l.outstanding)));if(!principal||principal<=0)return;const outstanding=Number(prompt('Current outstanding balance (₹)',String(l.outstanding)));if(outstanding<0||Number.isNaN(outstanding))return;const item={...l,principal,outstanding,accountId:l.accountId||accounts[0]?.id};saveList('pw_v3_loans',loans.map(x=>x.id===l.id?item:x),setLoans);const linked=transactions.find(t=>t.linkedType==='loan'&&t.linkedId===l.id);const loanTx={id:linked?.id??Date.now()+1,title:'Loan received: '+l.name,type:'income',kind:'loan_disbursement',amount:principal,category:'Loan',date:linked?.date||today(),accountId:item.accountId,linkedType:'loan',linkedId:l.id,note:'Automatically synced from Loans & EMI'};persist('pw_v2_transactions',linked?transactions.map(t=>t.id===linked.id?loanTx:t):[loanTx,...transactions],setTransactions)};
