 const persist=(key,value,setter)=>{try{const json=JSON.stringify(value),v7=V7_LEGACY_WRITE_MAP[key];if(v7)localStorage.setItem(v7,json);localStorage.setItem(key,json);setter(value)}catch(err){console.error('Pennywise could not save data',err);alert('Pennywise could not save this change. Your browser storage may be full. Download a backup and free some storage before continuing.')}};
 const saveTx=e=>{e.preventDefault();if(!txForm.title.trim()||Number(txForm.amount)<=0)return;const item={...txForm,id:editId??Date.now(),amount:Number(txForm.amount),kind:txForm.type,ledgerVersion:7,createdAt:editId?(transactions.find(t=>t.id===editId)?.createdAt||new Date().toISOString()):new Date().toISOString(),updatedAt:new Date().toISOString(),accountId:accounts.some(a=>a.id===Number(txForm.accountId))?Number(txForm.accountId):accounts[0]?.id};persist('pw_v2_transactions',editId?transactions.map(t=>t.id===editId?item:t):[item,...transactions],setTransactions);setModal('');setEditId(null);setTxForm(emptyTx)};
